{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    # Validate inputs
    if not isinstance(budget, int):
        raise ValueError('budget must be integer')
    names = set()
    min_sum = 0
    cap_sum = 0
    for i, seg in enumerate(segments):
        name = seg.get('name')
        importance = seg.get('importance')
        minimum = seg.get('minimum')
        capacity = seg.get('capacity')
        if not all(isinstance(x, int) for x in (importance, minimum, capacity)):
            raise ValueError(f'segment {i} fields not integers')
        if not isinstance(name, str):
            raise ValueError(f'segment {i} name not string')
        if name in names:
            raise ValueError(f'duplicate name {name}')
        names.add(name)
        if not (0 <= minimum <= capacity):
            raise ValueError(f'segment {i} invalid minimum/capacity')
        min_sum += minimum
        cap_sum += capacity
    if budget < min_sum:
        raise ValueError('budget below total minimum')
    if budget > cap_sum:
        raise ValueError('budget above total capacity')
    # Initialize allocations to minima
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - min_sum
    # Greedily allocate remaining tokens
    while remaining > 0:
        best_idx = None
        best_marg = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                marginal = seg['importance'] / (allocations[i] + 1)
                if marginal > best_marg:
                    best_marg = marginal
                    best_idx = i
        if best_idx is None:
            break  # safety, should not happen if feasible
        allocations[best_idx] += 1
        remaining -= 1
    # Build output
    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }
